// ============================
// FILTER DEADLINES – DAILY RUN
// (Schedule runs once per day)
// ============================

const r = $json;

// ---- Current time (UTC internally) ----
const now = new Date();

// ---- Compare two dates based on IST date only ----
function sameISTDate(a, b) {
  return a.toLocaleDateString("en-IN", { timeZone: "Asia/Kolkata" }) ===
         b.toLocaleDateString("en-IN", { timeZone: "Asia/Kolkata" });
}

// ---- Parse Google Sheets numeric serial dates ----
function parseSheetSerial(x) {
  const n = Number(x);
  if (!Number.isFinite(n)) return null;
  const ms = Math.round((n - 25569) * 86400 * 1000);
  const d = new Date(ms);
  return isNaN(d) ? null : d;
}

// ---- Normalize due_at for matching ----
function normalizeDueString(s) {
  if (!s) return "";
  let t = String(s).trim().replace(/\s+/g, " ");

  if (/ist$/i.test(t)) {
    t = t.replace(/\s*ist$/i, " IST");
  } else if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}$/.test(t)) {
    t = t + " IST";
  }

  return t;
}

// ---- Convert due_at text to real Date object ----
function parseDue(dueAtRaw) {
  if (!dueAtRaw) return null;

  // A) Sheets serial number
  const serial = parseSheetSerial(dueAtRaw);
  if (serial) return serial;

  // B) Try native Date parse
  let d = new Date(dueAtRaw);
  if (!isNaN(d)) return d;

  const s0 = String(dueAtRaw).trim();

  // C) "YYYY-MM-DD HH:mm IST"
  let m = s0.match(
    /^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})\s*IST$/i
  );
  if (m) {
    const iso = `${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:00+05:30`;
    d = new Date(iso);
    if (!isNaN(d)) return d;
  }

  // D) "YYYY-MM-DD HH:mm" (assume IST)
  m = s0.match(
    /^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})$/
  );
  if (m) {
    const iso = `${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:00+05:30`;
    d = new Date(iso);
    if (!isNaN(d)) return d;
  }

  // E) Fallback → add IST zone if missing
  const hasZone = /Z|[+\-]\d{2}:?\d{2}$/i.test(s0);
  const iso2 = hasZone ? s0 : s0.replace(" ", "T") + "+05:30";
  d = new Date(iso2);
  return isNaN(d) ? null : d;
}

// ---- Skip if completed or muted ----
if ((r.status || "").toLowerCase() === "completed") return;
if ((r.muted  || "").toLowerCase() === "1") return;

// ---- chat_id validation ----
const chatIdStored = r.chat_id ?? r.chatId ?? "";
if (!chatIdStored) return;

const chatIdNum = Number(chatIdStored);

// ---- Parse due date ----
const dueRaw  = r.due_at || r.dueAt || r.due || "";
const dueNorm = normalizeDueString(dueRaw);
const dueDate = parseDue(dueNorm);
if (!dueDate) return;

// ---- Keep only tasks due TODAY (IST) ----
if (!sameISTDate(dueDate, now)) return;

// ---- Avoid duplicate reminders on same IST day ----
const lastSent = r.last_sent_on ? parseDue(r.last_sent_on) : null;
if (lastSent && sameISTDate(lastSent, now)) return;

// ---- Build reminder ----

// Check if due_at has an explicit time (HH:mm)
const hasTime = /\d{2}:\d{2}/.test(dueNorm);

let human;
if (hasTime) {
  // Date + time (e.g. "Sat 22 Nov, 16:00")
  human = dueDate.toLocaleString("en-GB", {
    timeZone: "Asia/Kolkata",
    weekday: "short",
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
} else {
  // Date only (e.g. "Sat 22 Nov")
  human = dueDate.toLocaleString("en-GB", {
    timeZone: "Asia/Kolkata",
    weekday: "short",
    day: "2-digit",
    month: "short",
  });
}

// Assignee (optional)
const who = r.assignee ? ` for ${r.assignee}` : "";

// Final message
const msg = hasTime
  ? `⏰ Reminder${who}: ${r.task || "(no task text)"} — ${human} IST`
  : `⏰ Reminder${who}: ${r.task || "(no task text)"} — ${human}`;

// Use existing row_key from sheet if available
const row_key = r.row_key || `${chatIdStored}|${dueNorm}`;

return {
  json: {
    chat_id: chatIdNum,
    text: msg,
    task: r.task || "",
    assignee: r.assignee || "",
    due_at: dueNorm,
    row_key,
    last_sent_on: now
      .toLocaleString("en-GB", {
        timeZone: "Asia/Kolkata",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      })
      .replace(
        /(\d{2})\/(\d{2})\/(\d{4}),\s(\d{2}):(\d{2})/,
        "$3-$2-$1 $4:$5"
      ) + " IST",
  },
};

