// =======================
// Sanitize Input (Code) - UPDATED
// =======================

// 1) Get current time in UTC (no double conversion)
const now = new Date();

// Format: "YYYY-MM-DD HH:mm IST" (for logging / downstream)
const currentDateStr = now
  .toLocaleString('en-GB', {
    timeZone: 'Asia/Kolkata',   // display in IST only
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  })
  .replace(/(\d{2})\/(\d{2})\/(\d{4}),\s(\d{2}):(\d{2})/, '$3-$2-$1 $4:$5')
  + ' IST';

// 2) Parse Telegram input
const input = $input.all()[0].json;
const text = (input.message?.text || '').trim();
const chat_id = String(input.message?.chat?.id || '');

if (!text || !chat_id) {
  return [{
    json: {
      intent: 'error',
      chatInput: text,
      chat_id,
      reply: 'Unable to process message.',
      currentDate: currentDateStr,
    },
  }];
}

const lowerText = text.toLowerCase();

// -----------------------------
// INTENT DETECTION
// -----------------------------

let intent = 'create';
let reply = null;

// -- Smalltalk detection --
const smalltalkPatterns = [
  /^(hi|hello|hey|sup|yo|greetings|good morning|good afternoon|good evening)\b/i,
  /^(thanks|thank you|thx|ty)\b/i,
  /^(bye|goodbye|see you|cya)\b/i,
  /^(how are you|what's up|wassup)\b/i,
  /^(ok|okay|cool|nice|great|awesome)$/i,
];

if (smalltalkPatterns.some((p) => p.test(text))) {
  intent = 'smalltalk';

  if (/^(hi|hello|hey|sup|yo|greetings|good morning|good afternoon|good evening)\b/i.test(text)) {
    reply = 'Hello! How can I help you with your tasks today?';
  } else if (/^(thanks|thank you|thx|ty)\b/i.test(text)) {
    reply = "You're welcome! 😊";
  } else if (/^(bye|goodbye|see you|cya)\b/i.test(text)) {
    reply = 'Goodbye! Have a great day!';
  } else if (/^(how are you|what's up|wassup)\b/i.test(text)) {
    reply = "I'm doing great! Ready to help you manage your tasks.";
  } else {
    reply = 'Got it! 👍';
  }

  return [{
    json: {
      intent,
      chatInput: text,
      chat_id,
      reply,
      currentDate: currentDateStr,
    },
  }];
}

// -- Ask date detection --
if (
  /\b(what|whats|what's)\s+(is\s+)?(the\s+)?(date|day|today)\b/i.test(text) ||
  /\b(today|current date|todays date)\?*$/i.test(text)
) {
  intent = 'ask_date';

  const dayName = now.toLocaleDateString('en-US', {
    weekday: 'long',
    timeZone: 'Asia/Kolkata',
  });
  const day = now.toLocaleDateString('en-US', {
    day: 'numeric',
    timeZone: 'Asia/Kolkata',
  });
  const month = now.toLocaleDateString('en-US', {
    month: 'long',
    timeZone: 'Asia/Kolkata',
  });
  const year = now.toLocaleDateString('en-US', {
    year: 'numeric',
    timeZone: 'Asia/Kolkata',
  });

  reply = `Today is ${dayName} ${day} ${month} ${year} IST`;

  return [{
    json: {
      intent,
      chatInput: text,
      chat_id,
      reply,
      currentDate: currentDateStr,
    },
  }];
}

// -- Ask chat_id detection --
if (
  /\b(what|whats|what's)\s+(is\s+)?(my\s+)?(chat\s*id|chatid|id)\b/i.test(text)
) {
  intent = 'ask_chatid';
  reply = `Your chat ID is: ${chat_id}`;
  return [{
    json: {
      intent,
      chatInput: text,
      chat_id,
      reply,
      currentDate: currentDateStr,
    },
  }];
}

// -- List detection --
if (
  // e.g. "list my tasks", "show my tasks"
  /\b(list|show|display|view|get|see)\b.*\b(task|tasks|deadline|deadlines|todo|todos)\b/i.test(text) ||

  // e.g. "my tasks", "all tasks"
  /\b(my|all)\s+(task|tasks|deadline|deadlines|todo|todos)\b/i.test(text) ||

  // e.g. just "tasks?"
  /^(tasks|deadlines|todos)\?*$/i.test(text) ||

  // e.g. "what are the task for vashu"
  /\bwhat\s+are\s+the\s+(task|tasks)\b/i.test(text) ||

  // e.g. "tasks for vashu", "task for neha"
  /\b(task|tasks)\s+for\s+[a-z]+\b/i.test(text)
) {
  intent = 'list';
  return [{
    json: {
      intent,
      chatInput: text,
      chat_id,
      status: /\b(completed|done|finished)\b/i.test(text) ? 'completed' : 'pending',
      currentDate: currentDateStr,
    },
  }];
}

// -- Complete detection --
if (
  /^(complete|completed|done|finish|finished|mark\s+as\s+done)\b/i.test(text) ||
  /\b(complete|completed|done|finish|finished)\s+(task|tasks)\b/i.test(text) ||
  /\bmark\s+(the\s+)?(task|tasks)\s+(as\s+)?(complete|completed|done|finished)\b/i.test(text)
) {
  intent = 'complete';

  let taskText = text;

  // Extract assignee (for/by/of name OR @name)
  let assignee = '';
  const assigneeMatch =
    text.match(/\b(for|by|of)\s+([a-z]+)\b/i) ||
    text.match(/@([a-z]+)/i);

  if (assigneeMatch) {
    assignee = assigneeMatch[2] || assigneeMatch[1];
    taskText = taskText.replace(assigneeMatch[0], '').trim();
  }

  // Remove complete keywords from task text
  taskText = taskText.replace(
    /^(complete|completed|done|finish|finished|mark\s+as\s+done)\b/i,
    ''
  ).trim();
  taskText = taskText.replace(
    /\b(complete|completed|done|finish|finished)\s+(task|tasks)\b/i,
    ''
  ).trim();
  taskText = taskText.replace(/\s+/g, ' ').trim();

  const row_key = '';

  return [{
    json: {
      intent,
      chatInput: text,
      chat_id,
      assignee,
      task: taskText,
      status: 'pending',
      row_key,
      currentDate: currentDateStr,
    },
  }];
}

// -----------------------------
// CREATE TASK INTENT
// -----------------------------

let task = text;
let assignee = '';
let due_at = '';

// Extract assignee (for|to|assign to name OR @name)
const assigneePatterns = [
  /\b(for|to|assign\s+to)\s+([a-z]+)\b/i,
  /@([a-z]+)/i,
];

for (const pattern of assigneePatterns) {
  const match = text.match(pattern);
  if (match) {
    assignee = match[2] || match[1];
    task = task.replace(match[0], '').trim();
    break;
  }
}

// ---- Date parsing helper ----
function parseDateToken(dateStr, referenceDate) {
  const lower = dateStr.toLowerCase().trim();
  const ref = referenceDate; // now (UTC-based, but okay for relative calc)

  // Today
  if (lower === 'today') {
    return {
      year: ref.getFullYear(),
      month: ref.getMonth(),
      day: ref.getDate(),
    };
  }

  // Tomorrow
  if (lower === 'tomorrow') {
    const d = new Date(ref.getFullYear(), ref.getMonth(), ref.getDate());
    d.setDate(d.getDate() + 1);
    return {
      year: d.getFullYear(),
      month: d.getMonth(),
      day: d.getDate(),
    };
  }

  // Weekday names
  const weekdays = [
    'sunday', 'monday', 'tuesday', 'wednesday',
    'thursday', 'friday', 'saturday',
  ];
  const targetDay = weekdays.indexOf(lower);
  if (targetDay !== -1) {
    const currentDay = ref.getDay();
    let daysToAdd = targetDay - currentDay;
    if (daysToAdd <= 0) daysToAdd += 7;
    const d = new Date(ref.getFullYear(), ref.getMonth(), ref.getDate());
    d.setDate(d.getDate() + daysToAdd);
    return {
      year: d.getFullYear(),
      month: d.getMonth(),
      day: d.getDate(),
    };
  }

  // Absolute dates:
  // "14 nov 2025", "nov 14 2025", "2025-11-14"
  const datePatterns = [
    /^(\d{1,2})\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{4})$/i,
    /^(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{1,2})\s+(\d{4})$/i,
    /^(\d{4})-(\d{2})-(\d{2})$/,
  ];

  const months = {
    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
  };

  for (const pattern of datePatterns) {
    const match = lower.match(pattern);
    if (match) {
      let year, month, day;
      if (pattern.source.includes('jan|feb')) {
        if (match[1].length <= 2) {
          // "14 nov 2025"
          day = parseInt(match[1], 10);
          month = months[match[2].substring(0, 3)];
          year = parseInt(match[3], 10);
        } else {
          // "nov 14 2025"
          month = months[match[1].substring(0, 3)];
          day = parseInt(match[2], 10);
          year = parseInt(match[3], 10);
        }
      } else {
        // "2025-11-14"
        year = parseInt(match[1], 10);
        month = parseInt(match[2], 10) - 1;
        day = parseInt(match[3], 10);
      }
      return { year, month, day };
    }
  }

  return null;
}

// ---- Extract date token & time token from the text ----

// 1) Try to find date words in the text
const datePatternsForText = [
  /\b(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i,
  /\b(\d{1,2})\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{4})\b/i,
  /\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{1,2})\s+(\d{4})\b/i,
  /\b(\d{4})-(\d{2})-(\d{2})\b/,
];

let dateToken = null;
for (const pattern of datePatternsForText) {
  const match = text.match(pattern);
  if (match) {
    dateToken = match[0];
    task = task.replace(match[0], '').trim();
    break;
  }
}

// 2) Extract time (e.g. "12PM", "3 pm", "14:30", "9:15am")
let hour = null;
let minute = null;

// First try 12-hour with am/pm (with or without colon)
let timeMatch =
  text.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);

if (!timeMatch) {
  // Then try 24-hour "HH:MM"
  timeMatch = text.match(/\b(\d{1,2}):(\d{2})\b/);
}

if (timeMatch) {
  hour = parseInt(timeMatch[1], 10);
  minute = parseInt(timeMatch[2] || '0', 10);

  const ampm = (timeMatch[3] || '').toLowerCase();
  if (ampm === 'pm' && hour < 12) {
    hour += 12;
  } else if (ampm === 'am' && hour === 12) {
    hour = 0;
  }

  task = task.replace(timeMatch[0], '').trim();
}

// 3) Build due_at
let dateInfo = null;
if (dateToken) {
  dateInfo = parseDateToken(dateToken, now);
} else if (hour !== null) {
  // time only → treat as today
  dateInfo = {
    year: now.getFullYear(),
    month: now.getMonth(),
    day: now.getDate(),
  };
}

if (dateInfo) {
  const year = dateInfo.year;
  const monthStr = String(dateInfo.month + 1).padStart(2, '0');
  const dayStr = String(dateInfo.day).padStart(2, '0');

  if (hour !== null && minute !== null) {
    const hourStr = String(hour).padStart(2, '0');
    const minStr = String(minute).padStart(2, '0');
    due_at = `${year}-${monthStr}-${dayStr} ${hourStr}:${minStr} IST`;
  } else {
    // Only date, no time
    due_at = `${year}-${monthStr}-${dayStr}`;
  }
}

// Clean up task text
task = task
  .replace(/\s+/g, ' ')
  .replace(/^(by|on|at|for|to)\s+/i, '')
  .trim();

// Unique row_key based on chat + timestamp
const row_key = `${chat_id}-${now.getTime()}`;

return [{
  json: {
    intent: 'create',
    task,
    assignee,
    due_at,
    chat_id,
    row_key,
    status: 'pending',
    chatInput: text,
    currentDate: currentDateStr,
  },
}];
